                z[i] += 1
            if i + z[i] - 1 > r:
                l = i
                r = i + z[i] - 1
        z[0] = n
        return z

    combined = needle + '#' + haystack
    z = z_array(combined)
    for i in range(len(combined)):
        if z[i] >= len(needle):
            return i - len(needle)
    return -1
